function runMicroChecks(){
 const out=[];const eq=(id,label,actual,expected)=>{const pass=JSON.stringify(actual)===JSON.stringify(expected);out.push({id,label,actual,expected,pass});if(!pass)throw Error(label)};
 const refusal=(id,label,fn)=>{let failed=false;try{fn()}catch{failed=true}eq(id,label,failed,true)};
 function weighted(rows){let n=0,base=0,yes=0;const ids=new Set();for(const r of rows){if(ids.has(r.id)||!Number.isFinite(r.w)||r.w<0)throw Error("invalid");ids.add(r.id);if(r.v===null)continue;if(![0,1].includes(r.v))throw Error("answer");n++;base+=r.w;yes+=r.w*r.v;}if(!base)throw Error("base");return{n,base,proportion:yes/base};}
 const data=[{id:"a",w:1,v:1},{id:"b",w:3,v:0},{id:"c",w:2,v:null}];
 eq(602,"Exclude missing",weighted(data),{n:2,base:4,proportion:0.25});eq(602,"Repeat deterministic",weighted(data),weighted(data));
 refusal(602,"Duplicate ID",()=>weighted([...data,data[0]]));refusal(602,"Zero base",()=>weighted([{id:"a",w:0,v:1}]));refusal(602,"Negative weight",()=>weighted([{id:"a",w:-1,v:1}]));
 function stock(parts){if(!parts.length)throw Error("empty");return Math.min(...parts.map(p=>{if(!Number.isInteger(p.n)||p.n<0||!Number.isInteger(p.q)||p.q<=0)throw Error("invalid");return Math.floor(p.n/p.q);}));}
 eq(596,"Component multiple",stock([{n:15,q:2},{n:8,q:1}]),7);eq(596,"Empty component",stock([{n:0,q:1}]),0);refusal(596,"Zero requirement",()=>stock([{n:3,q:0}]));eq(596,"Concurrent snapshot can oversell",stock([{n:1,q:1}])+stock([{n:1,q:1}])>1,true);
 const esc=s=>s.replaceAll("&","&amp;").replaceAll("<","&lt;").replaceAll(">","&gt;").replaceAll('"',"&quot;");
 function cart(lines){let total=0;const seen=new Set();for(const l of lines){if(seen.has(l.sku)||!Number.isInteger(l.cents)||l.cents<0||!Number.isInteger(l.qty)||l.qty<=0)throw Error("invalid");seen.add(l.sku);total+=l.cents*l.qty;}return{total:(total/100).toFixed(2),items:lines.map(l=>`<Item sku="${esc(l.sku)}">${esc(l.description)}</Item>`).join("")};}
 eq(606,"Integer cent total",cart([{sku:"a",cents:1999,qty:3,description:"x"}]).total,"59.97");eq(606,"XML escaping",cart([{sku:"a",cents:1,qty:1,description:"a & <b>"}]).items,'<Item sku="a">a &amp; &lt;b&gt;</Item>');refusal(606,"Duplicate SKU",()=>cart([{sku:"a",cents:1,qty:1,description:"x"},{sku:"a",cents:1,qty:1,description:"x"}]));refusal(606,"Fractional cents",()=>cart([{sku:"a",cents:1.5,qty:1,description:"x"}]));
 return out;
}
